cp dist/web/opencode-bridge.js dist/web/opencode-bridge.js 2>/dev/null; cat > dist/web/opencode-bridge.js << "BRIDGE"
(function(){const WS_URL=(location.protocol==="https:"?"wss:":"ws:")+"//"+location.host+"/ws";let ws=null,rt=null,nextId=100;const seen=new Set();const NAME_PALETTE={"gentle-orchestrator":4};function d(data){window.dispatchEvent(new MessageEvent("message",{data}))}function ensure(n,pn,st){if(seen.has(n))return;seen.add(n);const id=nextId++,pa=NAME_PALETTE[n]??(nextId%6);const label=pn?pn+(st?" — "+st:""):n;d({type:"agentCreated",id,name:label,folderName:pn||n,palette:pa});d({type:"agentStatus",id,status:"active"})}function connect(){try{ws=new WebSocket(WS_URL);ws.onopen=()=>{if(rt){clearTimeout(rt);rt=null}};ws.onmessage=(e)=>{try{const m=JSON.parse(e.data);if(m.type==="agent_spawn")ensure(m.name||m.id,m.projectName,m.sessionTitle);if(m.type==="session_event")ensure(m.agentName||m.sessionID,m.projectName,m.sessionTitle);if(m.type==="state_update"&&m.agents)Object.keys(m.agents).forEach(n=>ensure(n))}catch(_){}};ws.onclose=()=>{rt=setTimeout(connect,3000)}}catch(_){rt=setTimeout(connect,3000)}}setTimeout(connect,1000)})();
BRIDGE
